Given a binary tree containing n nodes. The task is to find the sum of all nodes on the longest path from root to leaf node. If two or more paths compete for the longest path, then the path having the maximum sum of nodes is considered.Examples: Input: root[] = [4, 2, 5, 1, 3]Output: 13Explanation: The highlighted nodes (4, 2, 3) above are part of the longest root to leaf path having sum = (4 + 2 + 3) = 9Input: root[] = [4, 2, 5, 7, 1, 2, 3, N, N, 6, N]Output: 13Explanation:The highlighted nodes (4, 2, 1, 6) above are part of the longest root to leaf path having sum = (4 + 2 + 1 + 6) = 13Try It YourselfTable of Content[Better Approach] Using level order traversal - O(n) Time and O(n) Space[Expected Approach] Using Recursive - O(n) Time and O(h) Space[Better Approach] Using level order traversal - O(n) Time and O(n) SpaceThe idea is to initialize maxSum and maxLen to 0, use a queue for level order traversal starting with the root, and while the queue is not empty, dequeue nodes and update maxLen and maxSum for leaf nodes, and enqueue their children with updated sums and lengths, finally returning maxSum.
            C++

    // C++ implementation to find the sum of nodes
// on the longest path from root to leaf node 
// using level order traversal

#include <bits/stdc++.h>
using namespace std;

struct Node {
    int data;
    Node* left, *right;
    Node(int x) {
        data = x; 
        left = right = nullptr;
    }
};

// Function to calculate the sum of the longest root to 
// leaf path using level order traversal
int sumOfLongRootToLeafPath(Node* root) {

    // Base case: if the tree is empty
    if (!root) return 0;

    // Initialize variables to stor
  	// e maximum length and sum
    int maxSum = 0;
    int maxLen = 0;

    // Queue for level order traversal, storing pairs of
  	// nodes and their corresponding sum and length
    queue<pair<Node*, pair<int, int>>> q;

  	// Starting with the root node, initial
  	// sum, and length
    q.push({root, {root->data, 1}}); 

    while (!q.empty()) {
        auto front = q.front();
        q.pop();

        Node* node = front.first;
        int sum = front.second.first;
        int len = front.second.second;

        // If it's a leaf node, check if we need
      	// to update maxLen and maxSum
        if (!node->left && !node->right) {
            if (len > maxLen) {
                maxLen = len;
                maxSum = sum;
            } else if (len == maxLen && sum > maxSum) {
                maxSum = sum;
            }
        }

        // Push left and right children 
      	// into the queue
        if (node->left) {
            q.push({node->left, {sum + node->left->data, len + 1}});
        }
        if (node->right) {
            q.push({node->right, {sum + node->right->data, len + 1}});
        }
    }

    return maxSum;
}

int main() {

    // binary tree formation
    //        4
    //       / \ 
    //      2   5
    //     / \ 
    //    1  3
    Node* root = new Node(4);
    root->left = new Node(2);
    root->right = new Node(5);
    root->left->left = new Node(1);
    root->left->right = new Node(3);

    cout << sumOfLongRootToLeafPath(root);

    return 0;
}


